"""Input validation before any agent runs (generated by G2C): one validator per agent."""
from e2a import BaseValidationService, ValidationResult


class ServiceValidation(BaseValidationService):
    def __init__(self) -> None:
        self.validator_registry = {
            'IntentAgent': self._validate_intent_agent,
            'EvidenceAgent': self._validate_evidence_agent,
            'InvestigatorAgent': self._validate_investigator_agent,
            'ProposalAgent': self._validate_proposal_agent,
            'ExecutionAgent': self._validate_execution_agent,
        }

    def _validate_intent_agent(self, state, config=None, **kwargs):
        return True, []  # TODO: the input IntentAgent requires

    def _validate_evidence_agent(self, state, config=None, **kwargs):
        return True, []  # TODO: the input EvidenceAgent requires

    def _validate_investigator_agent(self, state, config=None, **kwargs):
        return True, []  # TODO: the input InvestigatorAgent requires

    def _validate_proposal_agent(self, state, config=None, **kwargs):
        return True, []  # TODO: the input ProposalAgent requires

    def _validate_execution_agent(self, state, config=None, **kwargs):
        return True, []  # TODO: the input ExecutionAgent requires

    def _enforce_entitlement_gate(self, agent_name, state, config=None, **kwargs) -> ValidationResult:
        return ValidationResult(valid=True, errors=[], agent_name=agent_name)  # TODO: who may use which agent
